style.css:
@-moz-document url-prefix("http") {
/* 1) Make page canvas true black */
  html, body {
    background: #000 !important;
  }

  /* 2) Kill non-black backgrounds WITHOUT overriding text colors */
  *:not(img):not(video):not(canvas):not(svg):not(picture):not(source) {
    background-color: #000 !important;
    background-image: none !important; /* removes gradients */
    box-shadow: none !important;
  }

  /* 3) Keep media untouched */
  img, video, canvas, svg, picture, source {
    background: transparent !important;
    filter: none !important;
  }

  /* 4) Make common “panels/cards” not-grey */
  [class*="card"], [class*="panel"], [class*="modal"], [class*="dialog"],
  [class*="drawer"], [class*="popover"], [role="dialog"], [role="menu"],
  header, nav, aside, footer, main, section, article, div {
    background-color: #000 !important;
    background-image: none !important;
  }

  /* 5) Inputs readable but not grey */
  input, textarea, select, button {
    background-color: #000 !important;
    border-color: #111 !important;
  }

  /* 6) Borders: dim, not bright */
  *, *::before, *::after {
    border-color: #111 !important;
  }

  /* 7) Scrollbars (Chromium) */
  ::-webkit-scrollbar { width: 10px; }
  ::-webkit-scrollbar-track { background: #000; }
  ::-webkit-scrollbar-thumb { background: #111; }
  ::-webkit-scrollbar-thumb:hover { background: #1a1a1a; }

  /* 8) Selection */
  ::selection { background: #222 !important; }
}
